36	\begin{figure}[H]
37	\centering
38	\includegraphics[width=0.85\textwidth]{slides-images/slide-24.jpg}
39	\caption{滑动窗口：将输入的局部区域连接到隐藏层神经元，通过滑动窗口定义连接。关键问题：如何设置权重以检测特定特征？\protect\footnotemark}
40	\end{figure}
41	\footnotetext{Slides 第24页。}
42	
43	\begin{importantbox}{卷积操作的三个核心特性}
44	\begin{enumerate}
45	    \item \textbf{局部特征提取}：使用一组权重（滤波器/filter）提取\textbf{局部特征}
46	    \item \textbf{多滤波器}：使用\textbf{多个滤波器}提取不同类型的特征
47	    \item \textbf{参数共享}：每个滤波器的参数在空间上\textbf{共享}（spatial sharing），即同一个滤波器应用于图像的所有位置
48	\end{enumerate}
49	\end{importantbox}
